local a={}a.PERIOD=10;function a.new()return{streaming=false}end;function a.key(b,c)if c~="p"and c~="P"then return"ignore"end;if b.streaming then b.streaming=false;return"stop"end;b.streaming=true;return"start"end;function a.tick(b)if b.streaming then return"dump"end;return"skip"end;function a.auto(b,d)if a.tick(b)=="skip"then return"skip"end;if d then return"dump"end;b.streaming=false;return"leave"end;function a.finish(b)if not b.streaming then return false end;b.streaming=false;return true end;return a